class Sensor {
  constructor(unit) {
    this.unit = unit;
  }

  read(n) {
    return `${n}${this.unit}`;
  }
}

class ScaledSensor extends Sensor {
  read(n) {
    console.log(super.unit);
    return super.read(n * 10);
  }
}

const s = new ScaledSensor("m");
console.log(s.read(3));
console.log(s.unit);
